import{_ as e,o as l,c,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"10进制转36进制","description":"将一个10进制数转换为36进制数的过程涉及将该10进制数不断除以36，并记录余数。这些余数，从最后一个到第一个，构成了该数在36进制下的表示。在36进制中，我们使用数字0 9和字母a z来表示0到35。 详细步骤 假设我们有一个10进制数 num ，我们要将其转换为36进制。以下。","frontmatter":{"title":"10进制转36进制","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语法、变量与数据"],"description":"将一个10进制数转换为36进制数的过程涉及将该10进制数不断除以36，并记录余数。这些余数，从最后一个到第一个，构成了该数在36进制下的表示。在36进制中，我们使用数字0 9和字母a z来表示0到35。 详细步骤 假设我们有一个10进制数 num ，我们要将其转换为36进制。以下。","sidebarWeight":42,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/基本数据类型-数字/10进制转36进制.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/02-语法、变量与数据/10进制转36进制.md","filePath":"posts/JavaScript系统教程/02-语法、变量与数据/10进制转36进制.md"}'),d={name:"posts/JavaScript系统教程/02-语法、变量与数据/10进制转36进制.md"};function t(p,o,a,r,s,n){return l(),c("div",null,[...o[0]||(o[0]=[i('<div><h1 id="_10进制转36进制" tabindex="-1">10进制转36进制 <a class="header-anchor" href="#_10进制转36进制" aria-label="Permalink to &quot;10进制转36进制&quot;">​</a></h1><blockquote><p>本节目标：理解“10进制转36进制”的核心思路，并能把它用于实际开发或面试表达。 将一个10进制数转换为36进制数的过程涉及将该10进制数不断除以36，并记录余数。这些余数，从最后一个到第一个，构成了该数在36进制下的表示。在36进制中，我们使用数字0-9和字母a-z来表示0到35。</p></blockquote><h3 id="详细步骤" tabindex="-1">详细步骤 <a class="header-anchor" href="#详细步骤" aria-label="Permalink to &quot;详细步骤&quot;">​</a></h3><p>假设我们有一个10进制数 <code>num</code>，我们要将其转换为36进制。以下是详细步骤：</p><ol><li><strong>初始化一个空字符串</strong>：</li></ol><ul><li>这将用于构建36进制的结果。</li></ul><ol start="2"><li><strong>不断执行除法</strong>：</li></ol><ul><li>将 <code>num</code> 除以36，记录除法的余数。</li><li>将余数转换为相应的36进制字符：</li><li>如果余数是0-9，直接使用数字0-9。</li><li>如果余数是10-35，转换为字母a-z，其中10对应a，11对应b，依此类推到35对应z。</li><li>将得到的字符添加到结果字符串的前端（因为我们是从低位开始处理的）。</li></ul><ol start="3"><li><strong>更新数值</strong>：</li></ol><ul><li>更新 <code>num</code> 为原数除以36的商。</li><li>重复上述过程，直到 <code>num</code> 变为0。</li></ul><ol start="4"><li><strong>输出结果</strong>：</li></ol><ul><li>如果一开始 <code>num</code> 就是0，直接返回 &quot;0&quot;。</li><li>否则，返回构建的字符串。</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p>假设我们要将10进制数 123456 转换为36进制。</p><ol><li><strong>初始化</strong>：</li></ol><ul><li>结果字符串： <code>&quot;&quot;</code></li><li>当前数值： <code>123456</code></li></ul><ol start="2"><li><strong>第一次除法</strong>：</li></ol><ul><li>123456 ÷ 36 = 3429，余数是12</li><li>余数12对应36进制的 &#39;c&#39;</li><li>结果字符串： <code>&quot;c&quot;</code></li></ul><ol start="3"><li><strong>第二次除法</strong>：</li></ol><ul><li>3429 ÷ 36 = 95，余数是9</li><li>余数9对应36进制的 &#39;9&#39;</li><li>结果字符串： <code>&quot;9c&quot;</code></li></ul><ol start="4"><li><strong>第三次除法</strong>：</li></ol><ul><li>95 ÷ 36 = 2，余数是23</li><li>余数23对应36进制的 &#39;n&#39;</li><li>结果字符串： <code>&quot;n9c&quot;</code></li></ul><ol start="5"><li><strong>第四次除法</strong>：</li></ol><ul><li>2 ÷ 36 = 0，余数是2</li><li>余数2对应36进制的 &#39;2&#39;</li><li>结果字符串： <code>&quot;2n9c&quot;</code></li></ul><ol start="6"><li><strong>输出结果</strong>：</li></ol><ul><li>最终结果为 <code>&quot;2n9c&quot;</code></li></ul><p>这个结果表示123456在36进制下的表示是<code>&quot;2n9c&quot;</code>。</p><p>这种方法非常适用于任何需要将10进制转换为更高基数系统的场景，特别是在需要短字符串表示大整数的场合（例如短URL服务等）。这种转换在计算机科学和网络应用中非常有用。</p><p>在36进制数系统中，使用的数字包括从0到9的十个阿拉伯数字和从A到Z的二十六个英文字母（或小写字母a-z，具体使用哪种形式取决于具体应用），总共36个字符。这些字符用于表示36进制中的每一个位数的值。</p><h3 id="完整的36进制数字列表" tabindex="-1">完整的36进制数字列表 <a class="header-anchor" href="#完整的36进制数字列表" aria-label="Permalink to &quot;完整的36进制数字列表&quot;">​</a></h3><p>以下是36进制所使用的全部字符及其对应的10进制值：</p><ul><li><p><strong>数字</strong>:</p></li><li><p><code>0</code> (十进制0)</p></li><li><p><code>1</code> (十进制1)</p></li><li><p><code>2</code> (十进制2)</p></li><li><p><code>3</code> (十进制3)</p></li><li><p><code>4</code> (十进制4)</p></li><li><p><code>5</code> (十进制5)</p></li><li><p><code>6</code> (十进制6)</p></li><li><p><code>7</code> (十进制7)</p></li><li><p><code>8</code> (十进制8)</p></li><li><p><code>9</code> (十进制9)</p></li><li><p><strong>英文字母</strong>:</p></li><li><p><code>A</code> 或 <code>a</code> (十进制10)</p></li><li><p><code>B</code> 或 <code>b</code> (十进制11)</p></li><li><p><code>C</code> 或 <code>c</code> (十进制12)</p></li><li><p><code>D</code> 或 <code>d</code> (十进制13)</p></li><li><p><code>E</code> 或 <code>e</code> (十进制14)</p></li><li><p><code>F</code> 或 <code>f</code> (十进制15)</p></li><li><p><code>G</code> 或 <code>g</code> (十进制16)</p></li><li><p><code>H</code> 或 <code>h</code> (十进制17)</p></li><li><p><code>I</code> 或 <code>i</code> (十进制18)</p></li><li><p><code>J</code> 或 <code>j</code> (十进制19)</p></li><li><p><code>K</code> 或 <code>k</code> (十进制20)</p></li><li><p><code>L</code> 或 <code>l</code> (十进制21)</p></li><li><p><code>M</code> 或 <code>m</code> (十进制22)</p></li><li><p><code>N</code> 或 <code>n</code> (十进制23)</p></li><li><p><code>O</code> 或 <code>o</code> (十进制24)</p></li><li><p><code>P</code> 或 <code>p</code> (十进制25)</p></li><li><p><code>Q</code> 或 <code>q</code> (十进制26)</p></li><li><p><code>R</code> 或 <code>r</code> (十进制27)</p></li><li><p><code>S</code> 或 <code>s</code> (十进制28)</p></li><li><p><code>T</code> 或 <code>t</code> (十进制29)</p></li><li><p><code>U</code> 或 <code>u</code> (十进制30)</p></li><li><p><code>V</code> 或 <code>v</code> (十进制31)</p></li><li><p><code>W</code> 或 <code>w</code> (十进制32)</p></li><li><p><code>X</code> 或 <code>x</code> (十进制33)</p></li><li><p><code>Y</code> 或 <code>y</code> (十进制34)</p></li><li><p><code>Z</code> 或 <code>z</code> (十进制35)</p></li></ul><h3 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h3><p>36进制常用于需要较短字符串来表示较大数字的场景，如短网址服务中的URL缩短，或在其他需要生成短但唯一标识符的应用中。这种方法通过增加表示数的位的基数来减少所需表示数的位数，从而使得表示更为紧凑。</p><p>在编程实践中，转换为36进制可以简单使用JavaScript的<code>toString(36)</code>方法，这使得任何数字可以轻松转换为此种高基数系统的字符串表示。</p></div>',1)])])}const h=e(d,[["render",t]]);export{g as __pageData,h as default};
